#include "../loader/windows/executable_integrity.h"
#include <cassert>
#include <vector>
#include <string>
#include <filesystem>
static DWORD integrity(){HANDLE token=nullptr;assert(OpenProcessToken(GetCurrentProcess(),TOKEN_QUERY,&token));DWORD size=0;GetTokenInformation(token,TokenIntegrityLevel,nullptr,0,&size);std::vector<unsigned char> data(size);assert(GetTokenInformation(token,TokenIntegrityLevel,data.data(),size,&size));CloseHandle(token);auto label=reinterpret_cast<TOKEN_MANDATORY_LABEL*>(data.data());return *GetSidSubAuthority(label->Label.Sid,*GetSidSubAuthorityCount(label->Label.Sid)-1);}
static DWORD child(const std::wstring &path){std::wstring cmd=L"\""+path+L"\" child";STARTUPINFOW si{};si.cb=sizeof si;PROCESS_INFORMATION pi{};assert(CreateProcessW(path.c_str(),cmd.data(),nullptr,nullptr,FALSE,0,nullptr,nullptr,&si,&pi));WaitForSingleObject(pi.hProcess,10000);DWORD result=0;assert(GetExitCodeProcess(pi.hProcess,&result));CloseHandle(pi.hThread);CloseHandle(pi.hProcess);return result;}
static std::vector<unsigned char> dacl(const std::wstring &path){DWORD n=0;GetFileSecurityW(path.c_str(),DACL_SECURITY_INFORMATION,nullptr,0,&n);assert(n);std::vector<unsigned char> data(n);assert(GetFileSecurityW(path.c_str(),DACL_SECURITY_INFORMATION,data.data(),n,&n));return data;}
int wmain(int argc,wchar_t**){if(argc>1)return integrity()==SECURITY_MANDATORY_LOW_RID?10:integrity()==SECURITY_MANDATORY_MEDIUM_RID?20:30;wchar_t dir[MAX_PATH],name[MAX_PATH];assert(GetTempPathW(MAX_PATH,dir));assert(GetTempFileNameW(dir,L"svi",0,name));assert(DeleteFileW(name)&&CreateDirectoryW(name,nullptr));std::filesystem::path path=std::filesystem::path(name)/L"fixture.exe";wchar_t self[32768];assert(GetModuleFileNameW(nullptr,self,32768));assert(CopyFileW(self,path.c_str(),TRUE));auto before=dacl(path.wstring());PSECURITY_DESCRIPTOR sd=nullptr;assert(ConvertStringSecurityDescriptorToSecurityDescriptorW(L"S:(ML;;NW;;;LW)",SDDL_REVISION_1,&sd,nullptr));assert(SetFileSecurityW(path.c_str(),LABEL_SECURITY_INFORMATION,sd));LocalFree(sd);assert(child(path.wstring())==10);assert(executable_integrity::medium(path.wstring()));assert(child(path.wstring())==20);assert(dacl(path.wstring())==before);assert(DeleteFileW(path.c_str()));assert(RemoveDirectoryW(name));return 0;}
